#!/usr/bin/env python3
"""One-off WebDriver BiDi check of the sequence page (not committed)."""
import base64
import json
import os
import socket
import struct
import time

HOST, PORT = '127.0.0.1', 9222


def connect():
    sock = socket.create_connection((HOST, PORT), timeout=30)
    chave = base64.b64encode(os.urandom(16)).decode()
    pedido = (
        'GET /session HTTP/1.1\r\n'
        'Host: %s:%d\r\n'
        'Upgrade: websocket\r\n'
        'Connection: Upgrade\r\n'
        'Sec-WebSocket-Key: %s\r\n'
        'Sec-WebSocket-Version: 13\r\n\r\n'
    ) % (HOST, PORT, chave)
    sock.sendall(pedido.encode())
    resposta = b''
    while b'\r\n\r\n' not in resposta:
        resposta += sock.recv(4096)
    assert b' 101 ' in resposta.split(b'\r\n')[0], resposta[:200]
    return sock


def recv_exato(sock, tamanho):
    dados = b''
    while len(dados) < tamanho:
        parte = sock.recv(tamanho - len(dados))
        if not parte:
            raise EOFError('conexao fechada')
        dados += parte
    return dados


def enviar_texto(sock, texto):
    dados = texto.encode('utf-8')
    cabecalho = bytearray([0x81])
    if len(dados) < 126:
        cabecalho.append(0x80 | len(dados))
    elif len(dados) < 65536:
        cabecalho.append(0x80 | 126)
        cabecalho += struct.pack('>H', len(dados))
    else:
        cabecalho.append(0x80 | 127)
        cabecalho += struct.pack('>Q', len(dados))
    mascara = os.urandom(4)
    cabecalho += mascara
    mascarado = bytes(b ^ mascara[i % 4] for i, b in enumerate(dados))
    sock.sendall(bytes(cabecalho) + mascarado)


def receber(sock):
    primeiro, segundo = recv_exato(sock, 2)
    opcode = primeiro & 0x0f
    mascarado = segundo & 0x80
    tamanho = segundo & 0x7f
    if tamanho == 126:
        tamanho = struct.unpack('>H', recv_exato(sock, 2))[0]
    elif tamanho == 127:
        tamanho = struct.unpack('>Q', recv_exato(sock, 8))[0]
    mascara = recv_exato(sock, 4) if mascarado else b''
    dados = recv_exato(sock, tamanho)
    if mascarado:
        dados = bytes(b ^ mascara[i % 4] for i, b in enumerate(dados))
    return opcode, dados


def comando(sock, numero, metodo, params):
    enviar_texto(sock, json.dumps({'id': numero, 'method': metodo,
                                   'params': params}))
    while True:
        opcode, dados = receber(sock)
        if opcode == 0x9:
            continue
        if opcode != 0x1:
            continue
        mensagem = json.loads(dados)
        if mensagem.get('id') == numero:
            return mensagem


ESTADO = """JSON.stringify({
  texto: document.body.innerText,
  blocos: document.querySelectorAll('.acordes-container').length,
  hexagonos: document.querySelectorAll('df-hex').length,
  cards: document.querySelectorAll('.music-card').length,
  valorInput: (document.querySelector(
      'input[ng-model="Sequencia.novaSequencia"]') || {}).value,
  erros: Array.from(document.querySelectorAll('.text-danger'))
      .map(function (e) { return e.innerText; })
      .filter(function (t) { return t.trim() !== ''; })
})"""


def cadastrar_js(sequencia):
    return """(function () {
      var input = document.querySelector(
          'input[ng-model="Sequencia.novaSequencia"]');
      input.value = %s;
      input.dispatchEvent(new Event('input', {bubbles: true}));
      document.querySelector('form button[type=submit]').click();
      return input.value;
    })()""" % json.dumps(sequencia)


def main():
    sock = connect()
    print('session.new:', json.dumps(
        comando(sock, 1, 'session.new', {'capabilities': {}}))[:200])
    contextos = comando(sock, 2, 'browsingContext.getTree',
                        {})['result']['contexts']
    contexto = contextos[0]['context']
    alvo = {'context': contexto}

    print('navigate:', json.dumps(comando(sock, 3, 'browsingContext.navigate', {
        'context': contexto,
        'url': 'http://127.0.0.1:5010/#/porsequencia',
        'wait': 'complete',
    }))[:160])
    time.sleep(4)

    numero = 10

    def avaliar(rotulo, expressao, pausa=0):
        nonlocal numero
        numero += 1
        if pausa:
            time.sleep(pausa)
        resposta = comando(sock, numero, 'script.evaluate', {
            'expression': expressao,
            'target': alvo,
            'awaitPromise': False,
        })
        valor = resposta['result']['result'].get('value')
        print(rotulo, valor)
        return valor

    avaliar('INICIAL', ESTADO)
    avaliar('CADASTRA', cadastrar_js('Am, F, C, G'), pausa=3)
    avaliar('APOS_CADASTRO', ESTADO)
    avaliar('DUPLICADA', cadastrar_js('Bm, G, D, A'), pausa=2)
    avaliar('APOS_DUPLICADA', ESTADO)
    avaliar('SEM_RESULTADO', cadastrar_js('Zz, Zz'), pausa=3)
    avaliar('APOS_SEM_RESULTADO', ESTADO)
    sock.close()


if __name__ == '__main__':
    main()
